#include "noe.hpp"
#include <algorithm>
#include <iostream>
#include <stdexcept>
#include <unordered_map>
#include <unordered_set>

namespace noe {
namespace {
bool truthyValue(const NirValue&v){if(auto p=std::get_if<bool>(&v))return*p;if(auto p=std::get_if<std::int64_t>(&v))return*p!=0;if(auto p=std::get_if<double>(&v))return*p!=0.0;if(auto p=std::get_if<std::string>(&v))return!p->empty();return false;}
std::int64_t asInt(const NirValue&v){if(auto p=std::get_if<std::int64_t>(&v))return*p;if(auto p=std::get_if<bool>(&v))return*p?1:0;if(std::holds_alternative<std::monostate>(v))return 0;throw std::runtime_error("integer or pointer value required");}
double asDouble(const NirValue&v){if(auto p=std::get_if<double>(&v))return*p;if(auto p=std::get_if<std::int64_t>(&v))return static_cast<double>(*p);throw std::runtime_error("numeric value required");}
NirValue binary(const std::string&op,const NirValue&a,const NirValue&b){if(auto x=std::get_if<std::int64_t>(&a))if(auto y=std::get_if<std::int64_t>(&b)){if(op=="+")return*x+*y;if(op=="-")return*x-*y;if(op=="*")return*x**y;if(op=="/")return*x / *y;if(op=="%")return*x % *y;if(op=="==")return*x==*y;if(op=="!=")return*x!=*y;if(op=="<")return*x<*y;if(op=="<=")return*x<=*y;if(op==">")return*x>*y;if(op==">=")return*x>=*y;}if((std::holds_alternative<double>(a)||std::holds_alternative<std::int64_t>(a))&&(std::holds_alternative<double>(b)||std::holds_alternative<std::int64_t>(b))){double x=asDouble(a),y=asDouble(b);if(op=="+")return x+y;if(op=="-")return x-y;if(op=="*")return x*y;if(op=="/")return x/y;if(op=="==")return x==y;if(op=="!=")return x!=y;if(op=="<")return x<y;if(op=="<=")return x<=y;if(op==">")return x>y;if(op==">=")return x>=y;}if(auto x=std::get_if<std::string>(&a))if(auto y=std::get_if<std::string>(&b)){if(op=="+")return*x+*y;if(op=="==")return*x==*y;if(op=="!=")return*x!=*y;}if(op=="&&")return truthyValue(a)&&truthyValue(b);if(op=="||")return truthyValue(a)||truthyValue(b);throw std::runtime_error("unsupported binary operation "+op);}
std::uint64_t rawLoad(std::uintptr_t address,std::size_t width,bool vol){if(address==0)throw std::runtime_error("null pointer dereference");switch(width){case 1:return vol?*reinterpret_cast<volatile std::uint8_t*>(address):*reinterpret_cast<std::uint8_t*>(address);case 2:return vol?*reinterpret_cast<volatile std::uint16_t*>(address):*reinterpret_cast<std::uint16_t*>(address);case 4:return vol?*reinterpret_cast<volatile std::uint32_t*>(address):*reinterpret_cast<std::uint32_t*>(address);case 8:return vol?*reinterpret_cast<volatile std::uint64_t*>(address):*reinterpret_cast<std::uint64_t*>(address);default:throw std::runtime_error("unsupported memory load width");}}
void rawStore(std::uintptr_t address,std::size_t width,std::uint64_t value,bool vol){if(address==0)throw std::runtime_error("null pointer store");switch(width){case 1:if(vol)*reinterpret_cast<volatile std::uint8_t*>(address)=static_cast<std::uint8_t>(value);else*reinterpret_cast<std::uint8_t*>(address)=static_cast<std::uint8_t>(value);break;case 2:if(vol)*reinterpret_cast<volatile std::uint16_t*>(address)=static_cast<std::uint16_t>(value);else*reinterpret_cast<std::uint16_t*>(address)=static_cast<std::uint16_t>(value);break;case 4:if(vol)*reinterpret_cast<volatile std::uint32_t*>(address)=static_cast<std::uint32_t>(value);else*reinterpret_cast<std::uint32_t*>(address)=static_cast<std::uint32_t>(value);break;case 8:if(vol)*reinterpret_cast<volatile std::uint64_t*>(address)=static_cast<std::uint64_t>(value);else*reinterpret_cast<std::uint64_t*>(address)=static_cast<std::uint64_t>(value);break;default:throw std::runtime_error("unsupported memory store width");}}
}

std::string Interpreter::valueToString(const NirValue&v)const{if(std::holds_alternative<std::monostate>(v))return"null";if(auto p=std::get_if<std::int64_t>(&v))return std::to_string(*p);if(auto p=std::get_if<double>(&v))return std::to_string(*p);if(auto p=std::get_if<bool>(&v))return*p?"true":"false";return std::get<std::string>(v);}
int Interpreter::run(const NirProgram&p){try{runFunction(p,p.entry,{});return 0;}catch(const std::exception&e){std::cerr<<"NQR-R4000: runtime error: "<<e.what()<<"\n";return 1;}}
NirValue Interpreter::runFunction(const NirProgram&p,const NirFunction&fn,const std::vector<NirValue>&argv){if(fn.isExtern)throw std::runtime_error("cannot directly interpret extern function "+fn.name);std::unordered_map<std::string,NirValue>vars;std::unordered_map<std::string,std::uint64_t>cells;std::unordered_set<std::string>addressTaken;std::vector<NirValue>regs(fn.nextReg);for(std::size_t i=0;i<fn.params.size()&&i<argv.size();++i){vars[fn.params[i]]=argv[i];if(std::holds_alternative<std::int64_t>(argv[i]))cells[fn.params[i]]=static_cast<std::uint64_t>(std::get<std::int64_t>(argv[i]));}std::size_t pc=0;while(pc<fn.code.size()){const auto&i=fn.code[pc];auto get=[&](Reg r)->const NirValue&{if(r>=regs.size())throw std::runtime_error("invalid NIR register");return regs[r];};switch(i.op){case NirOp::Const:regs[*i.dest]=i.literal;break;case NirOp::Load:{if(addressTaken.count(i.text)){regs[*i.dest]=static_cast<std::int64_t>(cells[i.text]);break;}auto it=vars.find(i.text);if(it==vars.end())throw std::runtime_error("undefined variable "+i.text);regs[*i.dest]=it->second;break;}case NirOp::Store:{vars[i.text]=get(i.args[0]);if(auto n=std::get_if<std::int64_t>(&vars[i.text]))cells[i.text]=static_cast<std::uint64_t>(*n);else if(auto b=std::get_if<bool>(&vars[i.text]))cells[i.text]=*b?1:0;break;}case NirOp::AddressOf:addressTaken.insert(i.text);cells.try_emplace(i.text,0);regs[*i.dest]=static_cast<std::int64_t>(reinterpret_cast<std::uintptr_t>(&cells[i.text]));break;case NirOp::LoadMemory:{auto address=static_cast<std::uintptr_t>(asInt(get(i.args[0])));regs[*i.dest]=static_cast<std::int64_t>(rawLoad(address,i.width,i.isVolatile));break;}case NirOp::StoreMemory:{auto address=static_cast<std::uintptr_t>(asInt(get(i.args[0])));rawStore(address,i.width,static_cast<std::uint64_t>(asInt(get(i.args[1]))),i.isVolatile);break;}case NirOp::PtrOffset:{std::int64_t base=asInt(get(i.args[0]));std::int64_t delta=static_cast<std::int64_t>(i.target);if(i.args.size()>1)delta=asInt(get(i.args[1]))*static_cast<std::int64_t>(i.width);regs[*i.dest]=base+delta;break;}case NirOp::Cast:{auto v=get(i.args[0]);Type t=typeFromName(i.text);if(t.kind==TypeKind::Float)regs[*i.dest]=asDouble(v);else if(t.isInteger()||t.kind==TypeKind::Pointer)regs[*i.dest]=asInt(v);else regs[*i.dest]=v;break;}case NirOp::Unary:{auto v=get(i.args[0]);if(i.text=="!")regs[*i.dest]=!truthyValue(v);else if(i.text=="-"){if(auto n=std::get_if<std::int64_t>(&v))regs[*i.dest]=-*n;else regs[*i.dest]=-asDouble(v);}else regs[*i.dest]=v;break;}case NirOp::Binary:regs[*i.dest]=binary(i.text,get(i.args[0]),get(i.args[1]));break;case NirOp::Call:{std::vector<NirValue>a;for(auto r:i.args)a.push_back(get(r));auto user=std::find_if(p.functions.begin(),p.functions.end(),[&](const auto&x){return x.name==i.text&&!x.isExtern;});if(user!=p.functions.end()){regs[*i.dest]=runFunction(p,*user,a);break;}std::string error;if(i.text=="host"||i.text=="abi"){if(a.empty()||!std::holds_alternative<std::string>(a[0]))throw std::runtime_error(i.text+" requires a string service name");std::string service=std::get<std::string>(a[0]);std::vector<NirValue>serviceArgs(a.begin()+1,a.end());std::optional<NirValue>result;if(host_)result=callNoqeriAbi(host_,service,serviceArgs,error);if(!result)result=callNoqeriAbi(defaultNoqeriAbi(),service,serviceArgs,error);if(!result)throw std::runtime_error(error.empty()?"unknown ABI service "+service:error);regs[*i.dest]=*result;break;}std::optional<NirValue>result;if(host_)result=callNoqeriAbi(host_,i.text,a,error);if(!result)result=callNoqeriAbi(defaultNoqeriAbi(),i.text,a,error);if(!result)throw std::runtime_error(error.empty()?"unknown function "+i.text:error);regs[*i.dest]=*result;break;}case NirOp::Jump:pc=i.target;continue;case NirOp::JumpIfFalse:if(!truthyValue(get(i.args[0]))){pc=i.target;continue;}break;case NirOp::Return:return i.args.empty()?NirValue(std::monostate{}):get(i.args[0]);case NirOp::Nop:break;}++pc;}return std::monostate{};}
} // namespace noe
